/// Type scale. Inter and JetBrains Mono are bundled app fonts (Lock L19).
abstract final class DtType {
  static const sansFamily = 'Inter';
  static const monoFamily = 'JetBrainsMono';
  /// Welcome, pricing, admin overview header only. Never inside a clinical workflow.
  static const TextStyle display = TextStyle(fontFamily: sansFamily, fontSize: 28.0, height: 1.2143, fontWeight: FontWeight.w600, letterSpacing: -0.56);
  /// Page titles, drug name in the header, sheet titles.
  static const TextStyle title = TextStyle(fontFamily: sansFamily, fontSize: 20.0, height: 1.4000, fontWeight: FontWeight.w600, letterSpacing: -0.20);
  /// Section and tab headings, dialog titles, table group headers.
  static const TextStyle heading = TextStyle(fontFamily: sansFamily, fontSize: 16.0, height: 1.5000, fontWeight: FontWeight.w600);
  /// Reading text, clinical prose, form values.
  static const TextStyle body = TextStyle(fontFamily: sansFamily, fontSize: 15.0, height: 1.4667, fontWeight: FontWeight.w400);
  /// Medication names in rows and search results, list row primaries.
  static const TextStyle bodyStrong = TextStyle(fontFamily: sansFamily, fontSize: 15.0, height: 1.4667, fontWeight: FontWeight.w600);
  /// Field labels, badges, chips, tab labels, table headers, DCI lines.
  static const TextStyle label = TextStyle(fontFamily: sansFamily, fontSize: 13.0, height: 1.3846, fontWeight: FontWeight.w500);
  /// Metadata, timestamps, evidence footers, helper text.
  static const TextStyle caption = TextStyle(fontFamily: sansFamily, fontSize: 12.0, height: 1.3333, fontWeight: FontWeight.w400);
  /// Any column of numbers: tables, doses, amounts. Set font-feature-settings "tnum".
  static const TextStyle numeric = TextStyle(fontFamily: sansFamily, fontSize: 15.0, height: 1.4667, fontWeight: FontWeight.w500, fontFeatures: [FontFeature.tabularFigures()]);
  /// The single calculator or dose result. One per screen. Tabular figures.
  static const TextStyle result = TextStyle(fontFamily: sansFamily, fontSize: 36.0, height: 1.1111, fontWeight: FontWeight.w600, letterSpacing: -0.72, fontFeatures: [FontFeature.tabularFigures()]);
  /// Transaction IDs, versions, formulas, references codes.
  static const TextStyle mono = TextStyle(fontFamily: monoFamily, fontSize: 13.0, height: 1.3846, fontWeight: FontWeight.w400, fontFeatures: [FontFeature.tabularFigures()]);
}

/// Material theme built from the tokens. Widgets read DtColors / DtElevation with
/// `Theme.of(context).extension<DtColors>()!` — never a raw colour (Lock L35).
ThemeData dtTheme(Brightness brightness) {
  final c = brightness == Brightness.light ? DtColors.light : DtColors.dark;
  final e = brightness == Brightness.light ? DtElevation.light : DtElevation.dark;
  return ThemeData(
    brightness: brightness,
    useMaterial3: true,
    fontFamily: DtType.sansFamily,
    scaffoldBackgroundColor: c.bg,
    splashFactory: NoSplash.splashFactory,
    colorScheme: ColorScheme(
      brightness: brightness,
      primary: c.brand,
      onPrimary: c.onBrand,
      secondary: c.teal,
      onSecondary: c.onTeal,
      error: c.critical,
      onError: c.onBrand,
      surface: c.surface,
      onSurface: c.ink,
      outline: c.borderStrong,
      outlineVariant: c.border,
    ),
    dividerColor: c.border,
    textTheme: TextTheme(
      headlineSmall: DtType.display.copyWith(color: c.ink),
      titleLarge: DtType.title.copyWith(color: c.ink),
      titleMedium: DtType.heading.copyWith(color: c.ink),
      bodyLarge: DtType.body.copyWith(color: c.ink),
      bodyMedium: DtType.body.copyWith(color: c.ink),
      labelLarge: DtType.label.copyWith(color: c.ink),
      bodySmall: DtType.caption.copyWith(color: c.inkMuted),
    ),
    extensions: <ThemeExtension<dynamic>>[c, e],
  );
}
